Use `pg` (node-postgres) with `Pool`:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT ?? '5432'),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                // max connections (default: 10)
  min: 2,                 // keep alive minimum

  // Timeouts (ms)
  connectionTimeoutMillis: 5000,   // fail fast if can't acquire connection
  idleTimeoutMillis: 30000,        // release idle connections after 30s
  query_timeout: 10000,            // per-query timeout
  statement_timeout: 10000,        // server-side statement timeout

  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// Crash-loop guard: log but don't crash on idle client errors
pool.on('error', (err, client) => {
  console.error('Idle client error', err);
});

// Wrapper — always releases client
export async function query(text: string, params?: unknown[]) {
  const client = await pool.connect();
  try {
    return await client.query(text, params);
  } finally {
    client.release();
  }
}

// Transaction helper
export async function withTransaction<T>(
  fn: (client: PoolClient) => Promise<T>
): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Graceful shutdown
export async function closePool() {
  await pool.end();
}
```

Key points:

| Setting | Why |
|---|---|
| `connectionTimeoutMillis` | Fail fast vs. hang forever waiting for free connection |
| `idleTimeoutMillis` | Prevents stale connections after DB-side timeout |
| `statement_timeout` | Server enforces; survives client-side crash |
| `pool.on('error')` | Without this, unhandled error crashes process |
| `finally { client.release() }` | Prevents pool exhaustion on errors |

Set `max` = roughly (CPU cores × 2) + effective spindle count, capped at DB's `max_connections` minus headroom for other clients. Don't just leave it at 10.
